/** Nombre de herramienta o tag → clave de BRANDS (gana la primera coincidencia). */
const MATCHERS: [RegExp, string][] = [
  [/hubspot/i, "hubspot"],
  [/zapier/i, "zapier"],
  [/^make$/i, "make"],
  [/\bga4\b|google analytics/i, "googleanalytics"],
  [/tag manager/i, "googletagmanager"],
  [/search console/i, "googlesearchconsole"],
  [/semrush/i, "semrush"],
  [/pagespeed/i, "pagespeedinsights"],
  [/hotjar/i, "hotjar"],
  [/bigquery/i, "googlebigquery"],
  [/metabase/i, "metabase"],
  [/woocommerce/i, "woocommerce"],
  [/wordpress/i, "wordpress"],
  [/kinsta/i, "kinsta"],
  [/cloudflare/i, "cloudflare"],
  [/vercel/i, "vercel"],
  [/next\.?js/i, "nextdotjs"],
  [/payload/i, "payloadcms"],
  [/nginx/i, "nginx"],
  [/postgres/i, "postgresql"],
  [/redis/i, "redis"],
  [/neo4j/i, "neo4j"],
  [/minio/i, "minio"],
  [/ollama/i, "ollama"],
  [/qdrant/i, "qdrant"],
  [/n8n/i, "n8n"],
  [/claude/i, "claude"],
  [/obsidian/i, "obsidian"],
  [/docker/i, "docker"],
  [/tailscale/i, "tailscale"],
  [/grafana/i, "grafana"],
  [/vault/i, "vault"],
  [/authelia/i, "authelia"],
  [/uptime kuma/i, "uptimekuma"],
  [/figma/i, "figma"],
  [/google ads/i, "googleads"],
  [/meta ads|^meta$/i, "meta"],
  [/notion/i, "notion"],
  [/asana/i, "asana"],
  [/macbook|apple/i, "apple"],
  [/\bnix/i, "nixos"],
  [/wezterm/i, "wezterm"],
  [/helix/i, "helix"],
  [/yubikey|yubico/i, "yubico"],
  [/python/i, "python"],
]

export function brandFor(name?: string | null): Brand | null {
  if (!name) return null
  const hit = MATCHERS.find(([re]) => re.test(name))
  return hit ? BRANDS[hit[1]] : null
}
